32	impl RowGroupEncoder {
33	    pub async fn run(self) -> PolarsResult<()> {
34	        let RowGroupEncoder {
35	            mut morsel_rx,
36	            encoded_row_group_tx,
37	            arrow_schema,
38	            schema_descriptor,
39	            write_options,
40	            encodings,
41	            num_leaf_columns,
42	        } = self;
43	
44	        while let Ok(morsel) = morsel_rx.recv().await {
45	            let arrow_schema = Arc::clone(&arrow_schema);
46	            let schema_descriptor = Arc::clone(&schema_descriptor);
47	            let encodings = Buffer::clone(&encodings);
48	
49	            let row_group_encode_handle = async_executor::AbortOnDropHandle::new(
50	                async_executor::spawn(TaskPriority::High, async move {
51	                    let (df, morsel_permit) = morsel.into_inner();
52	                    let num_rows = df.height();
53	
54	                    let mut data: Vec<Vec<CompressedPage>> = Vec::with_capacity(num_leaf_columns);
55	
56	                    for fut in parallelize_first_to_local(
57	                        TaskPriority::High,
58	                        df.into_columns().into_iter().enumerate().map(|(i, c)| {
59	                            let arrow_schema = Arc::clone(&arrow_schema);
60	                            let schema_descriptor = Arc::clone(&schema_descriptor);
61	                            let encodings = Buffer::clone(&encodings);
62	
63	                            async move {
64	                                let parquet_type = &schema_descriptor.fields()[i];
65	                                let encodings = encodings[i].as_slice();
66	                                let array =
67	                                    c.as_materialized_series().rechunk().to_arrow_with_field(
68	                                        0,
69	                                        Cow::Borrowed(arrow_schema.get_at_index(i).unwrap().1),
70	                                        true,
71	                                    )?;
72	
73	                                let mut data: UnitVec<Vec<CompressedPage>> =
74	                                    UnitVec::with_capacity(num_leaf_columns);
75	
76	                                for encode_page_iter in array_to_columns(
77	                                    array,
78	                                    parquet_type.clone(),
79	                                    write_options,
80	                                    encodings,
81	                                )? {
82	                                    let compressed_pages: Vec<CompressedPage> =
83	                                        Compressor::new_from_vec(
84	                                            encode_page_iter.map(|result| {
85	                                                result.map_err(|e| {
86	                                                    ParquetError::FeatureNotSupported(format!(
87	                                                        "reraised in polars: {e}",
88	                                                    ))
89	                                                })
90	                                            }),
91	                                            write_options.compression,
92	                                            vec![],
93	                                        )
94	                                        .collect::<ParquetResult<_>>()?;
95	
96	                                    data.push(compressed_pages)
97	                                }
98	
99	                                PolarsResult::Ok(data)
100	                            }
101	                        }),
102	                    ) {
103	                        data.extend(fut.await?);
104	                    }
105	
106	                    Ok(EncodedRowGroup {
107	                        num_rows,
108	                        data,
109	                        morsel_permit,
110	                    })
111	                }),
112	            );
113	
114	            if encoded_row_group_tx
115	                .send(row_group_encode_handle)
116	                .await
117	                .is_err()
118	            {
119	                break;
120	            }
121	        }
122	
123	        Ok(())
124	    }
125	}
