26	pub fn get_unknown_extension_type_behavior() -> UnknownExtensionTypeBehavior {
27	    match UNKNOWN_EXTENSION_TYPE_BEHAVIOR.load(Ordering::Relaxed) {
28	        0 => UnknownExtensionTypeBehavior::LoadAsGeneric,
29	        1 => UnknownExtensionTypeBehavior::LoadAsStorage,
30	        2 => UnknownExtensionTypeBehavior::WarnAndLoadAsStorage,
31	        _ => unreachable!(),
