39	    metadata: Option<&str>,
40	) -> Option<ExtensionTypeInstance> {
41	    match REGISTRY.read().unwrap().get(name) {
42	        Some(Some(factory)) => Some(ExtensionTypeInstance(
43	            factory.create_type_instance(name, storage, metadata),
44	        )),
45	        Some(None) => None,
46	        None => match get_unknown_extension_type_behavior() {
47	            UnknownExtensionTypeBehavior::LoadAsStorage => None,
48	            UnknownExtensionTypeBehavior::LoadAsGeneric => {
49	                let typ = super::GenericExtensionType::new(
50	                    name.to_string(),
51	                    metadata.map(|s| s.to_string()),
52	                );
53	                Some(ExtensionTypeInstance(Box::new(typ)))
54	            },
55	            UnknownExtensionTypeBehavior::WarnAndLoadAsStorage => {
56	                if UNKNOWN_EXTENSION_TYPE_BEHAVIOR.swap(
57	                    UnknownExtensionTypeBehavior::LoadAsStorage as u8,
58	                    Ordering::Relaxed,
59	                ) == UnknownExtensionTypeBehavior::WarnAndLoadAsStorage as u8
60	                {
